    "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface LeadCapture {
  leadCaptureId: number;
  companyId?: number | null; // Nullable as per DB spec, but not read/supplied by public endpoint (ADR-001)
  fullName: string;
  email: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource: string;
  interestArea?: string | null;
  status: string;
  assignedTo?: number | null;
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string | null;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// GET ALL — POST /all_leadCaptures
// Does not filter by companyId as per architectural decision ADR-001 (TENANT_INDEPENDENT).
export async function getAllLeadCaptures(): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{}] }), // Backend expects plural key, empty object to get all
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// CREATE — action: 1
// For internal UI (not public submission), companyId can be passed if assigned.
export async function createLeadCapture(payload: Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    const errorData = await res.json();
    throw new Error(errorData.error || errorData.message || 'Error al crear lead');
  }
  return await res.json();
}

// UPDATE — action: 2
// For internal UI (not public submission), companyId can be passed if assigned.
export async function updateLeadCapture(id: number, payload: Partial<Omit<LeadCapture, "leadCaptureId" | "created_At" | "updated_at">>): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 2, "leadCaptureId": id, ...payload }] }),
  });
  if (!res.ok) {
    const errorData = await res.json();
    throw new Error(errorData.error || errorData.message || 'Error al actualizar lead');
  }
  return await res.json();
}

// DELETE — action: 3
// companyId is not required for deletion as per ADR-001 (TENANT_INDEPENDENT).
export async function deleteLeadCapture(id: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 3, "leadCaptureId": id }] }),
  });
  if (!res.ok) {
    const errorData = await res.json();
    throw new Error(errorData.error || errorData.message || 'Error al eliminar lead');
  }
}
