              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de la Empresa"
                  labelPlacement="floating"
                  value={formState.companyName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleFormChange('companyName', e.detail.value!)}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Teléfono"
                  labelPlacement="floating"
                  type="tel"
                  value={formState.phone}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleFormChange('phone', e.detail.value!)}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Título del Puesto"
                  labelPlacement="floating"
                  value={formState.jobTitle}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleFormChange('jobTitle', e.detail.value!)}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Mensaje"
                  labelPlacement="floating"
                  value={formState.message}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleFormChange('message', e.detail.value!)}
                />
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Fuente del Lead *"
                  labelPlacement="floating"
                  value={formState.leadSource}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => handleFormChange('leadSource', e.detail.value!)}
                >
                  <IonSelectOption value="Website">Sitio Web</IonSelectOption>
                  <IonSelectOption value="Referral">Referencia</IonSelectOption>
                  <IonSelectOption value="Campaign">Campaña</IonSelectOption>
                  <IonSelectOption value="Other">Otro</IonSelectOption>
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Área de Interés"
                  labelPlacement="floating"
                  value={formState.interestArea}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => handleFormChange('interestArea', e.detail.value!)}
                >
                  <IonSelectOption value="">Ninguno</IonSelectOption>
                  <IonSelectOption value="Fintech">Fintech</IonSelectOption>
                  <IonSelectOption value="Retail">Retail</IonSelectOption>
                  <IonSelectOption value="Services">Servicios</IonSelectOption>
                  <IonSelectOption value="Manufacturing">Manufactura</IonSelectOption>
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Estado *"
                  labelPlacement="floating"
                  value={formState.status}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => handleFormChange('status', e.detail.value!)}
                  disabled={!editLead} // Status only editable when editing an existing lead
                >
                  <IonSelectOption value="new">Nuevo</IonSelectOption>
                  <IonSelectOption value="contacted">Contactado</IonSelectOption>
                  <IonSelectOption value="qualified">Calificado</IonSelectOption>
                  <IonSelectOption value="disqualified">Descalificado</IonSelectOption>
                  <IonSelectOption value="converted">Convertido</IonSelectOption>
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Asignado a"
                  labelPlacement="floating"
                  value={formState.assignedTo}
                  onIonChange={(e: CustomEvent<HTMLIonSelectElement>) => handleFormChange('assignedTo', e.detail.value!)}
                >
                  <IonSelectOption value={null}>Sin Asignar</IonSelectOption>
                  {assignedEmployees.map(employee => (
                    <IonSelectOption key={employee.employeeId} value={employee.employeeId}>
                      {employee.fullName}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonItem lines="none">
                  <IonLabel>Aceptar Política de Privacidad *</IonLabel>
                  <IonInput
                    type="checkbox"
                    slot="end"
                    checked={formState.privacyConsentAccepted}
                    onIonChange={(e: CustomEvent<InputInputEventDetail>) => handleFormChange('privacyConsentAccepted', e.detail.checked)}
                  />
                </IonItem>
              </div>
            </div>
          </IonContent>
          <IonFooter className="ion-padding">
            <IonButton expand="block" onClick={handleSaveLead} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : (editLead ? 'Guardar Cambios' : 'Crear Lead')}
            </IonButton>
          </IonFooter>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar este lead? Esta acción no se puede deshacer.'}
          buttons={[
            { text: 'Cancelar', role: 'cancel', handler: () => setShowDeleteAlert(false) },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />

        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={toastMessage.toLowerCase().includes('éxito') ? 'success' : toastMessage.toLowerCase().includes('error') ? 'danger' : 'warning'}
        />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={5000}
          color="danger"
          onDidDismiss={() => setError('')}
        />
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
